""" #> IMPORTS =======================
================================== """

#> imports
import os
import sys
import numpy as np
import matplotlib.pyplot as plt

#> adding opus path
sys.path.insert(0, '../opus')

#> modules
import generate
import modules.parse as parse

#> declarations
outFolder = '../../arrival_order/data/increment' # increment data


""" #> LOADING =======================
================================== """

#> main run folder
def run_dir(outFolder):
    return generate.dataDir + outFolder

#> loads main run folder files
def load_run(outFolder):
    return parse.load(run_dir(outFolder))

#> loads every bin of every incremented param
def load_param(outFolder, folder):
    return parse.load_folders(os.path.join(run_dir(outFolder), folder))


""" #> READS DATA ====================
================================== """

#> loads the whole increment.py run
def read(**kwargs):

    #> kwargs
    outFolder = kwargs.get('outFolder', globals()['outFolder'])  # run folder (inside generate.dataDir)

    #> run info + redraws
    run = load_run(outFolder)

    #> every param: {folder: [bin 0, bin 1, ...]}
    data = {folder: load_param(outFolder, folder) for folder in run['info']['points']}

    return run, data


""" #> ANALYZE FNS ===================
================================== """

#> number of quads whose morph order matches the fermat order, per bin
def count_match(b_data):
    return [int(np.nansum(data['order_match'])) for data in b_data] # nan (non-quads) skipped


#> order_match vs. inc param value
def order_match(run, folder, b_data):
    
    #> bin values + match counts
    x = run['info']['points'][folder]
    y = np.array(count_match(b_data)) / len(b_data)
    
    #> initializing plot
    fig, ax = plt.subplots(1,1,figsize=(6,6))
    ax.grid(ls=':', alpha=0.5)
    ax.set_xlabel(folder)
    ax.set_ylabel('number of order matches')
    ax.set_ylim(0,1)
    
    #> plotting
    ax.plot(x, y, marker='o')
        
    plt.show()
    plt.close()
    
    return

""" #> MAIN ==========================
================================== """

#> main function
if __name__ == '__main__':

    #> name
    print('> '+os.path.basename(__file__))

    #> loading
    run, data = read(outFolder=outFolder)
    
    print(run.keys())

    #> example: fraction of quads whose morph order matches the fermat order, per bin
    for folder, b_data in data.items():
        
        order_match(run, folder, b_data)

    # end
# thank
